package com.enterprise.siem.config;
import java.io.*; import java.nio.file.*; import java.util.*; import java.util.regex.*;
public final class AppConfig { private static final Pattern ENV_REFERENCE=Pattern.compile("\\$\\{([A-Za-z_][A-Za-z0-9_]*)}"); private final Properties p=new Properties(); public AppConfig(String path) throws IOException { try(InputStream in=Files.newInputStream(Path.of(path))) { p.load(in); } } public String get(String k,String d){String environment=System.getenv("SENTINELX_"+k.toUpperCase(Locale.ROOT).replace('.','_'));return expand(environment!=null?environment:p.getProperty(k,d));} private String expand(String value){if(value==null)return null; Matcher matcher=ENV_REFERENCE.matcher(value); StringBuffer result=new StringBuffer(); while(matcher.find()){String replacement=System.getenv(matcher.group(1)); matcher.appendReplacement(result,Matcher.quoteReplacement(replacement==null?matcher.group(0):replacement));} matcher.appendTail(result); return result.toString();} public int integer(String k,int d){String value=get(k,""+d);try{return Integer.parseInt(value);}catch(NumberFormatException e){throw new IllegalArgumentException(k+" must be an integer",e);}} public boolean bool(String k,boolean d){String value=get(k,""+d);if(!value.equalsIgnoreCase("true")&&!value.equalsIgnoreCase("false"))throw new IllegalArgumentException(k+" must be true or false");return Boolean.parseBoolean(value);} }
